<script setup lang="ts">import {computed,onMounted,reactive,ref} from 'vue';import {api,day,fmt,json,today} from '@/lib/api';import PageHeader from '@/components/PageHeader.vue';import AppModal from '@/components/AppModal.vue';import EmptyState from '@/components/EmptyState.vue';import {Plus} from 'lucide-vue-next';const items=ref<any[]>([]),products=ref<any[]>([]),open=ref(false),editing=ref<any>(),form=reactive<any>({});const comprehensive=computed(()=>Number(form.productUnitCost||0)+Number(form.packagingUnitCost||0));async function load(){[items.value,products.value]=await Promise.all([api('/purchases'),api('/products')])}function show(x?:any){editing.value=x;const b=x?.batches?.[0],p=products.value.find(p=>p.id==b?.productId);Object.assign(form,x?{...x,purchaseDate:String(x.purchaseDate).slice(0,10),productId:b.productId,specification:b.specification,quantity:b.quantity,productUnitCost:b.productUnitCost,packagingUnitCost:b.packagingUnitCost}:{purchaseDate:today(),purchaseOrderNo:'',supplier:'',productId:products.value[0]?.id,specification:'',quantity:1,productUnitCost:p?.referenceProductCost||0,packagingUnitCost:p?.referencePackagingCost||0,notes:''});open.value=true}function productChanged(){const p=products.value.find(x=>x.id==form.productId);if(p){form.productUnitCost=Number(p.referenceProductCost);form.packagingUnitCost=Number(p.referencePackagingCost)}}async function save(){try{await api(editing.value?`/purchases/${editing.value.id}`:'/purchases',json(editing.value?'PATCH':'POST',form));open.value=false;load()}catch(e:any){alert(e.message)}}async function del(x:any){if(confirm('删除后会重算所有相关订单的 FIFO，确定继续？'))try{await api(`/purchases/${x.id}`,{method:'DELETE'});load()}catch(e:any){alert(e.message)}}onMounted(load)</script>
<template><PageHeader title="采购入库" subtitle="每条采购明细形成独立 FIFO 批次，产品与包材成本随批次保存"><el-button type="primary" :icon="Plus" @click="show()">新增采购</el-button></PageHeader><el-card shadow="never"><el-table :data="items" stripe empty-text="暂无采购记录"><el-table-column label="日期 / 采购单号" width="150"><template #default="{row}">{{day(row.purchaseDate)}}<div class="text-xs text-slate-400">{{row.purchaseOrderNo}}</div></template></el-table-column><el-table-column prop="supplier" label="厂家"/><el-table-column label="商品" min-width="180"><template #default="{row}"><b>{{row.batches[0]?.product.name}}</b><div class="text-xs text-slate-400">{{row.batches[0]?.product.sku}}</div></template></el-table-column><el-table-column label="规格"><template #default="{row}">{{row.batches[0]?.specification||'—'}}</template></el-table-column><el-table-column label="数量"><template #default="{row}">{{row.batches[0]?.quantity}}</template></el-table-column><el-table-column label="产品单价"><template #default="{row}">¥ {{fmt(row.batches[0]?.productUnitCost)}}</template></el-table-column><el-table-column label="包材/件"><template #default="{row}">¥ {{fmt(row.batches[0]?.packagingUnitCost)}}</template></el-table-column><el-table-column label="综合/件"><template #default="{row}">¥ {{fmt(Number(row.batches[0]?.productUnitCost)+Number(row.batches[0]?.packagingUnitCost))}}</template></el-table-column><el-table-column label="批次总成本" min-width="130"><template #default="{row}"><b>¥ {{fmt(row.batches[0]?.quantity*(Number(row.batches[0]?.productUnitCost)+Number(row.batches[0]?.packagingUnitCost)))}}</b></template></el-table-column><el-table-column label="操作" fixed="right" width="140"><template #default="{row}"><el-button link type="primary" @click="show(row)">编辑</el-button><el-button link type="danger" @click="del(row)">删除</el-button></template></el-table-column></el-table></el-card><AppModal :open="open" :title="editing?'编辑采购':'新增采购'" width="760px" @close="open=false"><el-form :model="form" label-position="top" @submit.prevent="save"><div class="grid gap-x-4 sm:grid-cols-2"><el-form-item label="采购日期" required><el-date-picker v-model="form.purchaseDate" type="date" value-format="YYYY-MM-DD" class="!w-full"/></el-form-item><el-form-item label="采购订单号" required><el-input v-model="form.purchaseOrderNo"/></el-form-item><el-form-item label="厂家" required><el-input v-model="form.supplier"/></el-form-item><el-form-item label="商品 / SKU" required><el-select v-model="form.productId" filterable class="w-full" @change="productChanged"><el-option v-for="p in products" :key="p.id" :label="`${p.name} · ${p.sku}`" :value="p.id"/></el-select></el-form-item><el-form-item label="规格"><el-input v-model="form.specification"/></el-form-item><el-form-item label="数量" required><el-input-number v-model="form.quantity" :min="1" class="!w-full" controls-position="right"/></el-form-item><el-form-item label="产品采购单价（CNY）"><el-input-number v-model="form.productUnitCost" :min="0" :precision="4" class="!w-full" controls-position="right"/></el-form-item><el-form-item label="包材成本/件（CNY）"><el-input-number v-model="form.packagingUnitCost" :min="0" :precision="4" class="!w-full" controls-position="right"/></el-form-item></div><el-descriptions :column="2" border class="mb-5"><el-descriptions-item label="综合成本/件">¥ {{fmt(comprehensive)}}</el-descriptions-item><el-descriptions-item label="批次总成本"><b>¥ {{fmt(comprehensive*Number(form.quantity||0))}}</b></el-descriptions-item></el-descriptions><el-form-item label="备注"><el-input v-model="form.notes" type="textarea"/></el-form-item><div class="flex justify-end gap-2"><el-button @click="open=false">取消</el-button><el-button type="primary" native-type="submit">保存并重算 FIFO</el-button></div></el-form></AppModal></template>
